## Code Example
```javascript
const express = require('express');
const app = express();
app.use(express.json());
let cas = [];
app.post('/caps', (req, res) => {
  const cap = {...req.body, id: Date.now().toString(), status: 'detected'};
  cas.push(cap);
  res.status(201).json(cap);
});
```

